effect.shader:
// S_Fluid Pro Ultimate - Physical Fluid Solver Reconstruction

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1,0)), f.x),
               mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

float fbm(vec2 p, float time) {
    float v = 0.0;
    float a = 0.5;
    mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
    for (int i = 0; i < 4; i++) {
        v += a * noise(p + time);
        p = rot * p * 2.1;
        a *= 0.5;
    }
    return v;
}

void main() {
    vec2 uv = acScreenNorm;
    float aspect = acScreenSize.x / acScreenSize.y;
    vec2 p = uv; p.x *= aspect;

    float t = acTime * (speed / 100.0) + evolution;
    vec2 emit = (sourcePoint / 500.0) + vec2(0.5 * aspect, 0.5);

    // 1. Velocity Field Calculation
    float eps = 0.05;
    vec2 nUV = p * (100.0 / max(turbSize, 1.0));
    float n1 = fbm(nUV, t * (turbSpeed / 100.0) * 0.1);

    // Central Force from Emitter
    float dist = distance(p, emit);
    float emitMask = smoothstep(emitRadius / 100.0, 0.0, dist);
    float rad = radians(rotation);
    vec2 dirVec = vec2(cos(rad), sin(rad));
    vec2 emitDir = dirVec * (force / 100.0) * emitMask;

    // Vorticity & Curl (Eddies)
    float dndx = (fbm(nUV + vec2(eps, 0.0), t * 0.1) - n1) / eps;
    float dndy = (fbm(nUV + vec2(0.0, eps), t * 0.1) - n1) / eps;
    vec2 curlDir = vec2(dndy, -dndx) * (vorticity / 10.0) * (turbAmount / 100.0);

    // Physics forces
    vec2 gForce = vec2(0.0, (gravity / 100.0) + (buoyancy / 100.0));

    // Resulting Flow Field
    vec2 flow = (emitDir + curlDir + gForce) * (intensity / 100.0);

    // 2. Advection with Viscosity
    // Advection defines how the "paint" moves along the flow
    float visFactor = mix(1.0, 0.05, viscosity / 100.0);
    vec2 flowOffset = flow * visFactor;

    // Swirl modifier
    if(swirl > 0.0) {
        float sRad = radians(swirl * 3.6);
        mat2 sRot = mat2(cos(sRad * n1), sin(sRad * n1), -sin(sRad * n1), cos(sRad * n1));
        flowOffset *= sRot;
    }

    vec2 sampleUV = uv - flowOffset;

    // 3. Dual-Pass Sampling & Shading
    vec4 src = texture2DCv(inputImg.texture, uv);
    vec4 fluid = texture2DCv(inputImg.texture, clamp(sampleUV, 0.0, 1.0));

    // Color Engine
    vec3 finalRgb = fluid.rgb;
    if(colorMode == 1) {
        float mixVal = clamp(length(flow) * 10.0 + (colorMix / 360.0), 0.0, 1.0);
        vec3 tint = mix(colorA.rgb, colorB.rgb, mixVal);
        finalRgb = mix(finalRgb, tint, length(flow) * 2.0);
    }

    // Post-Process: Shading & Bloom
    if(shading > 0.0) {
        vec4 blur = texture2DCv(blurBuf.texture, sampleUV);
        float shadow = smoothstep(0.5, 0.0, blur.a - fluid.a);
        finalRgb *= mix(1.0, 1.0 - shadow, shading / 100.0);
    }

    if(bloomIntensity > 0.0) {
        float lum = dot(finalRgb, vec3(0.299, 0.587, 0.114));
        float bloom = smoothstep(bloomThreshold / 100.0, 1.0, lum);
        finalRgb += finalRgb * bloom * (bloomIntensity / 100.0) * 2.0;
    }

    // Composite
    vec3 result;
    if(blendMode == 1) result = src.rgb + finalRgb;
    else if(blendMode == 2) result = 1.0 - (1.0 - src.rgb) * (1.0 - finalRgb);
    else result = mix(src.rgb, finalRgb, fluid.a);

    float finalAlpha = fluid.a * (opacity / 100.0);
    vec3 finalOutput = mix(src.rgb, result, blend);

    gl_FragColor = vec4(clamp(finalOutput, 0.0, 4.0), max(src.a, finalAlpha));
}
